import { Table, BooleanColumn, StringColumn, TableNameColumn, GuidColumn } from '../../db'

export const dl_definition = Table({
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.text_index_translations': true,
        update_synch: true,
    },
    extends: 'sys_metadata',
    extensible: true,
    label: 'Data Lookup Definitions',
    name: 'dl_definition',
    schema: {
        run_on_form_change: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Perform data lookup on forms whose value changes that match this definition.',
                    label: 'Run on form change',
                    plural: 'Run on form changes',
                },
            ],
        }),
        name: StringColumn({
            label: 'Name',
            mandatory: true,
        }),
        matcher_table: TableNameColumn({
            attributes: {
                base_start: true,
                base_table: 'dl_matcher',
                skip_root: true,
            },
            label: [
                {
                    hint: 'Specifies the table for which new/modified records will be matched against.',
                    label: 'Matcher Table',
                    plural: 'Matcher Tables',
                },
            ],
            mandatory: true,
            tableReference: true,
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                },
            ],
            primary: true,
        }),
        run_on_update: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Perform data lookup for records being updated that match this definition.',
                    label: 'Run on update',
                    plural: 'Run on updates',
                },
            ],
        }),
        source_table: TableNameColumn({
            attributes: {
                base_start: true,
            },
            label: [
                {
                    hint: 'Specifies the table for which new/modified records will be matched from.',
                    label: 'Source Table',
                    plural: 'Source Tables',
                },
            ],
            mandatory: true,
            tableReference: true,
        }),
        active: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Specifies whether lookup/replacements will occur.',
                    label: 'Active',
                    plural: 'Active',
                },
            ],
        }),
        run_on_insert: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Perform data lookup for records being inserted that match this definition.',
                    label: 'Run on insert',
                    plural: 'Run on inserts',
                },
            ],
        }),
    },
})
